<script setup lang="ts">
import { computed,onMounted,onUnmounted,reactive,ref,watch } from 'vue'
import { CheckCircle2,LogOut,RefreshCw,Save,ShieldCheck } from 'lucide-vue-next'
import { ApiError,all,api,dateTimeLabel,localDate,messageOf,query,taskStatuses,ui } from '../api'
import { useDraft,type Conflict } from '../drafts'
import type { LanDailyEntry,LanMember,LanTask,LanWorkspace } from '../lan'
import type { Page } from '../types'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
const member=ref<LanMember>(),workspace=ref<LanWorkspace>(),sessionExpires=ref(''),checking=ref(true),pairing=ref(false),loading=ref(false),saving=ref(false),loggingOut=ref(false),taskSaving=ref(''),error=ref(''),success=ref(''),project=ref(''),date=ref(localDate()),daily=ref<LanDailyEntry[]>([]),editing=ref<LanDailyEntry>(),dailyLoading=ref(false),editorReady=ref(false),taskConflict=ref(''),dailyConflict=ref<Conflict>(),remoteDaily=ref<LanDailyEntry>(),taskForms=reactive<Record<string,{status:string;progress:number;version:number}>>({}),pairForm=reactive({code:'',device_name:''}),taskScope=ref('today'),treeProject=ref('')
const form=reactive({content:'',next_plan:'',blockers:'',minutes:0}),local=useDraft(()=>`lan-daily:${member.value?.id||'anonymous'}:${project.value}:${date.value}`,form,()=>editorReady.value,()=>editing.value?.version),pending=computed(()=>saving.value||pairing.value||loggingOut.value||!!taskSaving.value),readonly=computed(()=>!workspace.value?.projects.some(p=>p.id===project.value&&!['closed','archived'].includes(p.status))),minutesInvalid=computed(()=>!Number.isInteger(Number(form.minutes))||Number(form.minutes)<0||Number(form.minutes)>1440),hasWork=computed(()=>!!form.content.trim()||!!form.next_plan.trim()||!!form.blockers.trim()||Number(form.minutes)>0),today=localDate()
const workHours=computed({get:()=>Math.floor(Number(form.minutes)/60),set:(value:number)=>{form.minutes=Number(value)*60+Number(form.minutes)%60}}),workMinutes=computed({get:()=>Number(form.minutes)%60,set:(value:number)=>{form.minutes=Math.floor(Number(form.minutes)/60)*60+Number(value)}})
const assignedTasks=computed(()=>(workspace.value?.tasks||[]).filter(t=>member.value?.task_ids.includes(t.id)&&!t.has_children).filter(t=>taskScope.value==='all'||t.status!=='done'&&(!t.plan_start||t.plan_start<=today)))
const scheduleRange=computed(()=>{const dates=projectTasks.value.flatMap(t=>[t.plan_start,t.plan_end]).filter(v=>/^\d{4}-\d{2}-\d{2}$/.test(v)).map(v=>Date.parse(v+'T00:00:00Z')).filter(Number.isFinite);return dates.length?{start:Math.min(...dates),end:Math.max(...dates)}:undefined})
function scheduleStyle(task:LanTask){const range=scheduleRange.value;if(!range||!task.plan_start||!task.plan_end)return {};const start=Date.parse(task.plan_start+'T00:00:00Z'),end=Date.parse(task.plan_end+'T00:00:00Z'),span=range.end-range.start+86400000;return {left:`${Math.max(0,(start-range.start)/span*100)}%`,width:`${Math.max(.5,(end-start+86400000)/span*100)}%`}}
const projectTasks=computed(()=>(workspace.value?.tasks||[]).filter(t=>!treeProject.value||t.project_id===treeProject.value)),currentProject=computed(()=>workspace.value?.projects.find(p=>p.id===project.value))
let dailyRequest=0
function projectLabel(id:string){return workspace.value?.projects.find(p=>p.id===id)?.name||'项目已不可用'}
function tasksDirty(){return Object.entries(taskForms).some(([id,form])=>{const task=workspace.value?.tasks.find(t=>t.id===id);return task&&task.can_update&&(task.status!==form.status||task.progress!==form.progress)})}
function canLeave(){if(pending.value)return false;if(editorReady.value&&!local.canLeave())return false;return !tasksDirty()||window.confirm('任务行中的进展修改尚未保存，确定继续？')}
function loseSession(message='会话已失效，请向负责人获取新的一次配对码。'){local.persist();editorReady.value=false;member.value=undefined;workspace.value=undefined;error.value=message;success.value=''}
function handle(e:unknown){if(e instanceof ApiError&&e.status===401)loseSession();else error.value=messageOf(e)}
async function check(){checking.value=true;error.value='';try{const data=await api<{member:LanMember;expires_at?:string}>('/api/lan/session');member.value=data.member;sessionExpires.value=data.expires_at||'';await loadWorkspace(false)}catch(e){if(e instanceof ApiError&&e.status===401){member.value=undefined;workspace.value=undefined}else handle(e)}finally{checking.value=false}}
async function pair(){if(pairing.value||!/^[a-fA-F0-9]{64}$/.test(pairForm.code.trim()))return;pairing.value=true;error.value='';try{const data=await api<{member:LanMember;expires_at?:string}>('/api/lan/pair',{method:'POST',body:JSON.stringify({code:pairForm.code.trim(),device_name:pairForm.device_name.trim()||'成员浏览器'})});pairForm.code='';member.value=data.member;sessionExpires.value=data.expires_at||'';await loadWorkspace(false);success.value='配对成功，当前浏览器可访问已授权工作内容。'}catch(e){handle(e)}finally{pairing.value=false}}
async function loadWorkspace(guard=true){if(guard&&!canLeave())return;loading.value=true;error.value='';try{const data=await api<LanWorkspace>('/api/lan/workspace');local.persist();workspace.value=data;member.value=data.member;ui.datasetId=data.dataset_id||`lan:${location.origin}:${data.member.id}`;ui.operator=data.member.name;for(const key of Object.keys(taskForms))delete taskForms[key];for(const task of data.tasks)taskForms[task.id]={status:task.status,progress:task.progress,version:task.version};if(!data.projects.some(p=>p.id===project.value))project.value=data.projects[0]?.id||'';if(!data.projects.some(p=>p.id===treeProject.value))treeProject.value=project.value;await loadDaily()}catch(e){handle(e)}finally{loading.value=false}}
function assign(entry?:LanDailyEntry){editing.value=entry;Object.assign(form,{content:entry?.content||'',next_plan:entry?.next_plan||'',blockers:entry?.blockers||'',minutes:entry?.minutes||0})}
async function loadDaily(){const seq=++dailyRequest;local.persist();editorReady.value=false;dailyLoading.value=true;error.value='';dailyConflict.value=undefined;remoteDaily.value=undefined;try{const entries=project.value?await all<LanDailyEntry>('/api/lan/my-daily',{project_id:project.value,work_date:date.value}):[];if(seq!==dailyRequest)return;daily.value=entries;assign(entries.find(e=>e.project_id===project.value&&e.work_date===date.value));editorReady.value=!!project.value;await local.reset()}catch(e){handle(e)}finally{if(seq===dailyRequest)dailyLoading.value=false}}
async function changeContext(event:Event,field:'project'|'date'){const value=(event.target as HTMLInputElement).value,previous=field==='project'?project.value:date.value;if(!canLeave()){(event.target as HTMLInputElement).value=previous;return}local.persist();editorReady.value=false;if(field==='project')project.value=value;else date.value=value;await loadDaily()}
async function save(){if(pending.value||dailyLoading.value||!editorReady.value||readonly.value||minutesInvalid.value||!hasWork.value)return;saving.value=true;error.value='';success.value='';const payload={project_id:project.value,work_date:date.value,...form,minutes:Number(form.minutes),...(editing.value?{id:editing.value.id,version:editing.value.version}:{})};try{const saved=await api<LanDailyEntry>('/api/lan/my-daily',{method:'POST',body:JSON.stringify(payload)});local.discard();assign(saved);await local.reset();daily.value=[saved];dailyConflict.value=undefined;remoteDaily.value=undefined;success.value='每日工作与工时已由服务器保存，负责人可汇总到项目日志。'}catch(e){handle(e);local.persist();if(e instanceof ApiError&&e.status===409){try{const result=await api<Page<LanDailyEntry>>(`/api/lan/my-daily?${query({project_id:project.value,work_date:date.value,limit:500})}`);remoteDaily.value=result.items.find(item=>item.project_id===project.value&&item.work_date===date.value);dailyConflict.value={local:JSON.parse(JSON.stringify(payload)),remote:remoteDaily.value?{...remoteDaily.value}:{},path:''}}catch(inner){handle(inner)}}}finally{saving.value=false}}
async function reloadDaily(){if(!remoteDaily.value)return;local.persist();assign(remoteDaily.value);dailyConflict.value=undefined;remoteDaily.value=undefined;await local.reset();error.value='已载入服务器版本，原本地修改保留在浏览器草稿中。'}
async function saveTask(task:LanTask){if(pending.value||!task.can_update||!taskForms[task.id])return;const draft=taskForms[task.id]!;if(!Number.isInteger(Number(draft.progress))||draft.progress<0||draft.progress>100)return;taskSaving.value=task.id;error.value='';success.value='';taskConflict.value='';try{const saved=await api<LanTask>(`/api/lan/tasks/${task.id}`,{method:'PATCH',body:JSON.stringify({version:draft.version,status:draft.status,progress:Number(draft.progress)})});const current=workspace.value?.tasks.find(t=>t.id===task.id);if(current)Object.assign(current,saved,{can_update:saved.can_update??(saved.status!=='done'&&current.can_update)});taskForms[task.id]={status:saved.status,progress:saved.progress,version:saved.version};success.value='任务进展已由服务器保存。完成后需负责人重开，才能继续修改。'}catch(e){handle(e);if(e instanceof ApiError&&e.status===409)taskConflict.value=task.id}finally{taskSaving.value=''}}
async function refreshTask(task:LanTask){if(!window.confirm('重新读取此任务将替换这一行尚未保存的状态和进度，继续？'))return;loading.value=true;error.value='';try{const data=await api<LanWorkspace>('/api/lan/workspace');const latest=data.tasks.find(t=>t.id===task.id);if(latest){Object.assign(task,latest);taskForms[task.id]={status:latest.status,progress:latest.progress,version:latest.version}}else{if(workspace.value)workspace.value.tasks=workspace.value.tasks.filter(t=>t.id!==task.id);delete taskForms[task.id]}taskConflict.value=''}catch(e){handle(e)}finally{loading.value=false}}
async function logout(){if(!canLeave())return;loggingOut.value=true;error.value='';try{await api('/api/lan/logout',{method:'POST',body:'{}'});loseSession('已退出此浏览器会话。需要继续访问时，请重新获取配对码。')}catch(e){handle(e)}finally{loggingOut.value=false}}
function taskChanged(task:LanTask){const draft=taskForms[task.id];if(!draft)return;if(draft.status==='done')draft.progress=100;else if(draft.progress===100)draft.progress=99}
function minutesLabel(value:number){return `${Math.floor(value/60)} 小时${value%60?` ${value%60} 分钟`:''}`}
function beforeUnload(event:BeforeUnloadEvent){if(tasksDirty()){event.preventDefault();event.returnValue=''}}
watch(()=>member.value?.id,()=>{if(!member.value)editorReady.value=false})
onMounted(check);onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload));defineExpose({canLeave})
</script>
<template><div class="member-workspace"><header class="member-header"><div class="member-brand"><span class="member-mark">P</span><div><strong>ProjNote</strong><small>局域网成员工作台</small></div></div><div v-if="member" class="member-header-actions"><span>{{member.name}}<small>成员 {{member.id.slice(0,8)}}</small></span><button type="button" class="button subtle small" :disabled="pending||loading" @click="loadWorkspace()"><RefreshCw :size="14"/>刷新</button><button type="button" class="button subtle small" :disabled="pending" @click="logout"><LogOut :size="14"/>退出</button></div><span v-else class="member-security"><ShieldCheck :size="16"/>限定项目与本人工作</span></header><main class="member-main"><p v-if="error" class="error-banner" role="alert">{{error}}</p><p v-if="success" class="member-success" role="status"><CheckCircle2 :size="17"/>{{success}}</p><p v-if="checking" class="loading-message">正在确认成员会话…</p><section v-else-if="!member" class="surface member-pair"><h1>连接你的项目工作</h1><p>向本机负责人获取一次配对码。在已核对并信任 HTTPS 证书的设备浏览器内配对，查看授权项目并提交自己的工作。</p><form @submit.prevent="pair"><fieldset :disabled="pairing"><label>一次配对码 <span class="required">*</span><input v-model="pairForm.code" required maxlength="64" minlength="64" pattern="[a-fA-F0-9]{64}" autocomplete="one-time-code" spellcheck="false" autofocus placeholder="负责人提供的 64 位配对码"/></label><label>设备名称<input v-model="pairForm.device_name" maxlength="100" placeholder="如：办公室电脑（可选）"/></label></fieldset><button class="button primary" :disabled="pairing||!/^[a-fA-F0-9]{64}$/.test(pairForm.code.trim())">{{pairing?'正在配对…':'配对此浏览器'}}</button></form><p class="input-hint">配对码一次有效、10 分钟到期；会话最长 7 天，负责人可随时撤销。无需管理员密码。这里不提供负责人管理、备份或其他成员日志。</p></section>
<template v-else-if="workspace"><div class="member-heading"><div><h1>我的项目工作</h1><p>{{today}} · 查看项目全貌，更新自己的指定任务与每日工作。</p></div><p v-if="sessionExpires" class="input-hint">会话有效期至 {{dateTimeLabel(sessionExpires)}}</p></div>
<section class="surface member-daily"><div class="section-heading"><div><h2>每日工作与工时</h2><p class="input-hint">每个项目、每个工作日保留一份本人记录，可继续修改。</p></div><button class="button primary small" type="submit" form="member-daily-form" :disabled="pending||loading||dailyLoading||!editorReady||readonly||minutesInvalid||!hasWork"><Save :size="15"/>{{saving?'正在保存…':'保存每日工作'}}</button></div><div class="member-daily-body"><div class="member-day-context"><label>项目<select :value="project" :disabled="pending||dailyLoading" aria-label="成员工作项目" @change="changeContext($event,'project')"><option value="" disabled>选择授权项目</option><option v-for="p in workspace.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>工作日期<input :value="date" type="date" required :disabled="pending||dailyLoading" aria-label="成员工作日期" @change="changeContext($event,'date')"/></label><p v-if="editing" class="input-hint">已保存版本 {{editing.version}}</p></div><p v-if="readonly" class="input-hint">{{currentProject?'项目已结项或归档，仅可查看记录。':'还没有授权项目，请联系负责人。'}}</p><p v-if="dailyLoading" class="loading-message">正在读取本人工作记录…</p><DraftNotice :value="local.available.value" :values="local.values.value" :error="local.storageError.value" :recovery="local.recovery.value" @select="local.select" @restore="local.restore" @force="local.restoreForced" @cancel-recovery="local.clearRecovery" @discard="local.discardAvailable"/><ConflictNotice :value="dailyConflict" @keep="local.persist();dailyConflict=undefined" @reload="reloadDaily"/><form id="member-daily-form" @submit.prevent="save"><fieldset :disabled="pending||loading||dailyLoading||!editorReady||readonly"><label>完成工作<textarea v-model="form.content" rows="5" maxlength="20000" placeholder="当天完成的工作、产出与结果"/></label><div class="form-row"><label>后续计划<textarea v-model="form.next_plan" rows="3" maxlength="10000"/></label><label>阻碍 / 需协调<textarea v-model="form.blockers" rows="3" maxlength="10000"/></label></div><div class="member-time-input"><strong>本项目当天投入</strong><div class="form-row member-time-parts"><label>小时<input v-model.number="workHours" type="number" min="0" max="24" step="1" required aria-label="项目工时小时"/></label><label>分钟<input v-model.number="workMinutes" type="number" min="0" max="59" step="1" required aria-label="项目工时分钟"/></label></div><span class="input-hint">{{minutesInvalid?'请输入有效的小时与分钟，合计不超过 24 小时':minutesLabel(Number(form.minutes))}}。0 可只提交日志。</span></div><p v-if="Number(form.minutes)>480" class="member-time-warning">超过 8 小时，请核对当天投入；此提示不阻止合理记录。</p></fieldset></form></div></section>
<section class="surface member-own-tasks"><div class="section-heading"><div><h2>我的指定任务 <span class="count">{{assignedTasks.length}}</span></h2><p class="input-hint">仅可更新由项目负责人指派给你的叶子任务。</p></div><select v-model="taskScope" aria-label="我的任务范围"><option value="today">今日待办及逾期</option><option value="all">全部指定任务</option></select></div><div v-if="assignedTasks.length" class="table-scroll"><table><thead><tr><th>任务 / 项目</th><th>计划日期</th><th>状态</th><th>进度</th><th class="right">操作</th></tr></thead><tbody><tr v-for="task in assignedTasks" :key="task.id"><td><strong>{{task.wbs_code}} {{task.name}}</strong><small>{{projectLabel(task.project_id)}}</small><p v-if="taskConflict===task.id" class="form-error">服务器任务已变化，本行修改保留。<button type="button" class="text-button" @click="refreshTask(task)">载入此任务新版本</button></p></td><td>{{task.plan_start||'未设置'}}<small>至 {{task.plan_end||'未设置'}}</small></td><td><select v-if="task.can_update&&taskForms[task.id]" v-model="taskForms[task.id]!.status" :aria-label="`${task.name} 状态`" :disabled="pending||loading" @change="taskChanged(task)"><option value="todo">未开始</option><option value="doing">进行中</option><option value="done">已完成</option></select><span v-else>{{taskStatuses[task.status]}}</span></td><td><input v-if="task.can_update&&taskForms[task.id]" v-model.number="taskForms[task.id]!.progress" :aria-label="`${task.name} 进度`" type="number" min="0" max="100" step="1" :disabled="pending||loading||taskForms[task.id]!.status==='done'"/><span v-else>{{task.progress}}%</span></td><td class="right"><button v-if="task.can_update" type="button" class="button subtle small" :disabled="pending||loading" @click="saveTask(task)">{{taskSaving===task.id?'正在保存…':'保存进展'}}</button><span v-else class="input-hint">{{task.status==='done'?'完成后由负责人重开':'只读'}}</span></td></tr></tbody></table></div><p v-else class="empty-state compact">此范围没有指定任务。可查看项目进展，或联系负责人确认任务授权。</p></section>
<section class="surface member-project-progress"><div class="section-heading"><div><h2>项目进展</h2><p class="input-hint">项目任务共用当前 WBS 与计划日期，其他成员的日志和管理资料不在此显示。</p></div><select v-model="treeProject" aria-label="查看项目进展"><option v-for="p in workspace.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></div><div v-if="projectTasks.length" class="table-scroll"><table><thead><tr><th>WBS / 任务</th><th>负责人</th><th>计划日期</th><th>进展</th></tr></thead><tbody><tr v-for="task in projectTasks" :key="task.id"><td><span :style="{paddingLeft:`${(task.depth||0)*14}px`}">{{task.wbs_code}} {{task.name}}</span></td><td>{{task.assignee||'未指定'}}</td><td><span>{{task.plan_start||'未设置'}} → {{task.plan_end||'未设置'}}</span><div v-if="task.plan_start&&task.plan_end&&scheduleRange" class="member-schedule" aria-label="项目统一日期轴上的计划区间"><i :style="scheduleStyle(task)"/></div></td><td><div class="member-progress"><i :style="{width:`${task.progress}%`}"/></div><small>{{taskStatuses[task.status]}} · {{task.progress}}%</small></td></tr></tbody></table></div><p v-else class="empty-state compact">此项目暂无可查看任务。</p></section>
